BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats4-q01', '仮説検定',
   'コインを10回投げたら8回表が出た。「イカサマ入りかも」と疑ったとき、仮説検定という考え方がまずやることはどれ？',
   NULL::text,
   '["「ふつうの五分五分のコイン」と仮に置き、その仮定でこの結果がどれくらい珍しいかを計算する", "表と裏の出た回数をそれぞれ丁寧に数えて、多かった方をそのまま「本物」だと決めてしまう", "同じコインをもっと何度も何度も投げ直してみれば、いつか必ず正しい答えがはっきり分かると考える", "コインを分解して重さや厚みを細かく測り、数字の計算ではなく物として不正を直接確かめる"]',
   0, '[0]', 'single',
   '{"asked": "「珍しいことが起きた」をどう判断するかという、仮説検定という考え方そのもの。", "point": "先に「差はない・ふつうだ」と仮に置いて、それでも起きにくいほど珍しいことが起きたなら、その仮定を疑う。これが仮説検定の骨組み。", "kid": "仮説検定は、いきなり「イカサマだ」とは言わない。まず「ふつうのコインだ」と仮に置いてみて、その仮定のままだとどれくらい珍しいことが起きたかを計算する道具。", "eg": "名探偵の推理と同じ。まず「みんな嘘をついていない」と仮に置いてみて、それだと辻褄が合わない証拠が出てきたら、最初の仮定のほうを疑う。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"10\" width=\"300\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"24\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">①「差はない」といったん仮に置く</text><text x=\"170\" y=\"36\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">（帰無仮説）</text><line x1=\"170\" y1=\"40\" x2=\"170\" y2=\"50\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><polygon points=\"165,50 175,50 170,56\" fill=\"#8892a4\"/><rect x=\"20\" y=\"56\" width=\"300\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"70\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">②その仮定の世界で今回の結果が</text><text x=\"170\" y=\"82\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">起きる確率を計算する</text><line x1=\"170\" y1=\"86\" x2=\"170\" y2=\"96\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><polygon points=\"165,96 175,96 170,102\" fill=\"#8892a4\"/><rect x=\"20\" y=\"102\" width=\"300\" height=\"30\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"170\" y=\"116\" fill=\"#60a5fa\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">③珍しすぎるなら①の仮定を疑う</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">（帰無仮説を退ける）</text></svg>", "terms": [["仮説検定", "「本当にただの偶然か」を、数字で確かめるための考え方の手順"], ["偶然", "何度もやれば、まぐれで起きることもある、というはたらき"]], "think": "なぜ「いったん仮に置く」というまわり道をするのかがカギ。最初から「イカサマだ」と決めつけると、ただの思い込みになってしまう。そこで先に「ふつうのコインだ（差はない）」と仮に置き、その仮定の世界で今回の結果がどれくらい起きやすいかを計算する。もしめったに起きないほど珍しいなら、「ふつうのコインだ」という最初の仮定のほうが怪しいと判断する。だから仮説検定は、疑いたい結論を直接証明するのではなく、逆の仮定を崩すという遠回りな形をとる。", "vs": "「表と裏の数をただ数えて多い方を選ぶ」のは仮説検定ではない。仮説検定は、数えた結果が「偶然でもよく起きる範囲」か「偶然ではめったに起きない範囲」かを判断する点が違う。", "why_asked": "「たまたま」と「本物」を人の感覚だけで見分けると、思い込みや勘違いが混ざる。誰がやっても同じ基準で判断できるように、仮に置いた仮定を崩せるかどうかで判断する手順が必要になった。", "usecase": "新しい薬が本当に効くか、広告を変えたらクリック率が本当に上がったか。「たまたまかもしれない」が常につきまとう場面で、判断のものさしとして使う。", "opt": ["正解。「ふつうのコインだ」といったん仮に置き、その仮定のもとで今回の結果がどれくらい珍しいかを確かめるのが仮説検定の考え方。", "回数を数えて多い方を選ぶだけでは、その差が偶然の範囲か珍しい範囲かが分からない。仮説検定は「珍しさ」を計算する手順を踏む。", "何度も投げ直せば必ず答えが分かるわけではない。ふつうのコインでも8回表が続くことはあり、回数を増やすだけでは疑いは晴れない。", "コインの重さや形を測るのは物理的な調査であり、結果の数字から偶然かどうかを判断する仮説検定とは別の話。"]}'),

  ('stats4-q02', '仮説検定',
   '新しい勉強法を試したクラスと、試していないクラスのテストの平均点を比べる。仮説検定でまず「差はない」といったん仮に置く、その仮定のことを何と呼ぶ？',
   NULL::text,
   '["帰無仮説", "対立仮説", "有意水準", "検出力"]',
   0, '[0]', 'single',
   '{"asked": "仮説検定で最初に「差はない」と仮に置く、その仮定の名前。", "point": "壊すために立てる仮定が帰無仮説。「差はない」「効果はない」のような、いったん無かったことにする仮定。", "kid": "帰無仮説は、「きっと差なんて無いだろう」といったん仮に置く仮定。名前の「帰無」は「無に帰る（無かったことにする）」という意味で、最初からこれを信じているわけではない。", "eg": "裁判の「疑わしきは罰せず」と似ている。まず「無罪（＝差はない）」からスタートして、それを覆すだけの証拠がそろって初めて「有罪（＝差がある）」と言う。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"80\" y=\"18\" width=\"180\" height=\"52\" rx=\"6\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"170\" y=\"40\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">帰無仮説</text><text x=\"170\" y=\"58\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">「新しい勉強法に差はない」</text><line x1=\"170\" y1=\"70\" x2=\"170\" y2=\"90\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 3\"/><text x=\"170\" y=\"104\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\">崩せるだけの証拠がそろえば退ける</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">＝壊すために先に立てる仮定</text></svg>", "terms": [["帰無仮説", "「差はない・効果はない」といったん仮に置く仮定。壊されるために立てる"], ["仮定", "本当かどうかまだ分からないが、話を進めるためにいったん正しいとしておく前提"]], "think": "なぜわざわざ「差はない」からスタートするのかがカギ。もし「新しい勉強法に効果がある」を直接証明しようとすると、「たまたま今回は良い結果が出ただけ」という言い訳がいつまでも残ってしまう。そこで先に「効果はない（帰無仮説）」を仮に置き、その仮定のもとでは今回の結果が起きにくいことを示せば、「効果はない」という仮定のほうを退けられる。壊すための的として先に立てるのが帰無仮説の役目。", "vs": "帰無仮説は「差はない」という守りの仮定で、本当に言いたいこと（「効果がある」）は対立仮説という別の名前で呼ぶ。両者は同じ検定の中の、表と裏の関係。", "why_asked": "「差がある」と言いたいときに、いきなりそれを主張すると水掛け論になる。先に崩すための的（帰無仮説）を決めておくことで、誰がやっても同じ手順で判定できるようにする必要があった。", "usecase": "新薬の効果検証では必ず「この薬は偽薬と効果に差がない」を帰無仮説に置く。A/Bテストでも「新デザインと旧デザインでクリック率に差はない」が帰無仮説になる。", "opt": ["正解。「差はない・効果はない」といったん仮に置き、壊すために立てる仮定が帰無仮説。", "対立仮説は「本当は差がある」という、証明したい側の仮定。帰無仮説とは逆の役割。", "有意水準は「珍しい」と判断する基準になる割合のことで、仮に置く仮定そのものではない。", "検出力は本当に差があるときにそれを見つけられる力のことで、最初に立てる仮定とは別の概念。"]}'),

  ('stats4-q03', '仮説検定',
   '新しい薬を試験した研究者が本当に確かめたいのは「この薬には効果がある」ということだった。仮説検定で、この「本当に言いたいこと」にあたる仮説を何と呼ぶ？',
   NULL::text,
   '["対立仮説", "帰無仮説", "有意水準", "棄却域"]',
   0, '[0]', 'single',
   '{"asked": "研究者が本当に主張したい内容を表す仮説の名前。", "point": "本当に言いたいことは対立仮説。帰無仮説（差はない）を退けられたときに、代わりに採用される仮説。", "kid": "対立仮説は、研究者が「本当はこうだと思っている」内容。帰無仮説（差はない）と向かい合う（対立する）位置にあるので、この名前がついている。", "eg": "法廷でいうと「有罪」の主張にあたる。検察官（研究者）は本当は「有罪（＝効果がある）」と言いたいが、まずは「無罪（＝差はない）」を土台にして、それを崩せるだけの証拠を積み上げていく。", "viz": "<svg viewBox=\"0 0 340 122\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"16\" y=\"24\" width=\"140\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"86\" y=\"46\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">帰無仮説</text><text x=\"86\" y=\"62\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">「差はない」</text><text x=\"86\" y=\"76\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">崩すための的</text><rect x=\"184\" y=\"24\" width=\"140\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"254\" y=\"46\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">対立仮説</text><text x=\"254\" y=\"62\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">「効果がある」</text><text x=\"254\" y=\"76\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">本当に言いたいこと</text><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">退けたら、代わりに対立仮説を採用する</text><line x1=\"156\" y1=\"54\" x2=\"184\" y2=\"54\" stroke=\"#8892a4\" stroke-dasharray=\"3 3\"/><text x=\"170\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">両者は必ずセットで、どちらか一方を採る</text></svg>", "terms": [["対立仮説", "研究者が本当に主張したい仮説。帰無仮説と反対の内容"], ["採用", "帰無仮説を退けたときに、代わりに正しいとみなすこと"]], "think": "なぜ「本当に言いたいこと」を直接検定の主役にしないのかがカギ。仮説検定の仕組みでは、帰無仮説（差はない）の世界で計算した「珍しさ」をもとに判断する。だから対立仮説（差がある）は、帰無仮説が退けられたときに「では代わりにこちらを採用する」という形で、間接的に浮かび上がる役目になる。研究者の本音は対立仮説にあるが、検定の計算そのものは帰無仮説を主役に進む。", "vs": "帰無仮説と対立仮説は必ずセットで、片方が退けられればもう片方が採用される二者択一の関係。どちらも先に決めておき、結果を見てから都合よく変えてはいけない。", "why_asked": "検定の結果を「効果があった・なかった」とだけ言うと曖昧になる。何と何を比べていたのかをはっきりさせるために、本当に言いたい内容を対立仮説として先に明文化しておく必要がある。", "usecase": "新薬の試験では「この薬には効果がある」が対立仮説。品質改善のA/Bテストでは「新しいやり方のほうが良い」が対立仮説にあたる。", "opt": ["正解。研究者が本当に主張したい「効果がある」にあたる仮説が対立仮説。", "帰無仮説は「差はない」という、崩すために先に立てる仮定。本当に言いたい内容とは逆側。", "有意水準は「珍しい」と判断する基準の割合のことで、主張の内容そのものではない。", "棄却域は帰無仮説を退けると判断する結果の範囲のことで、主張の名前ではない。"]}'),

  ('stats4-q04', '仮説検定',
   '新しい勉強法を試したクラスの平均点が、いつもより5点高かった。「帰無仮説（差はない）の世界で、これくらい極端な差が起きる確率」を表す数字を何と呼ぶ？',
   NULL::text,
   '["p値", "有意水準", "標準偏差", "偏差値"]',
   0, '[0]', 'single',
   '{"asked": "「帰無仮説の世界でこの結果、もしくはもっと極端な結果が起きる確率」を表す数字の名前。", "point": "p値は「差はない世界」での、この結果以上に珍しいことが起きる確率。p値が小さいほど、帰無仮説の世界では起きにくかったことになる。", "kid": "p値は、「もし本当に差がない（帰無仮説が正しい）としたら、今回みたいな差（かそれ以上の差）がどれくらいの確率で起きるか」を計算した数字。p値が小さいほど「差がない世界ではめったに起きない」ということになる。", "eg": "サイコロを6回振って6が4回出たとする。「ふつうのサイコロ」という前提のもとで、これくらい6が偏る確率を計算した数字がp値にあたる。小さければ小さいほど「ふつうのサイコロではなさそう」と疑いが強まる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 108 C 90 108, 110 22, 170 22 C 230 22, 250 108, 320 108\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"108\" x2=\"320\" y2=\"108\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M255 108 C 260 88, 270 60, 285 44 L 320 44 L 320 108 Z\" fill=\"#3b82f6\" opacity=\"0.45\"/><line x1=\"255\" y1=\"108\" x2=\"255\" y2=\"34\" stroke=\"#60a5fa\" stroke-dasharray=\"3 2\"/><text x=\"255\" y=\"26\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">実際の結果</text><text x=\"290\" y=\"96\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">p値</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">帰無仮説の世界で、これ以上に極端なことが起きる確率</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">＝ぬりつぶした面積の広さ</text></svg>", "terms": [["p値", "帰無仮説が正しいとしたときに、観測された結果以上に極端なことが起きる確率"], ["極端さ", "偶然からどれだけ離れているか、珍しさの度合い"]], "think": "なぜ「これくらい極端な結果が起きる確率」を計算するのかがカギ。仮説検定は、帰無仮説（差はない）の世界を仮に描き、その世界の中で今回のデータがどのくらいありふれているかを見る。5点差がその世界でよく起きる範囲ならp値は大きく、めったに起きない範囲ならp値は小さくなる。p値が十分小さければ、「差はない世界にしては、この結果は珍しすぎる」と判断し、帰無仮説を疑う材料にする。p値そのものは「対立仮説が正しい確率」ではなく、あくまで「帰無仮説のもとでの珍しさ」を測る数字であることに注意する。", "vs": "p値を「対立仮説が正しい確率」や「たまたまである確率」と読み違える人が多いが、正しくは「帰無仮説が正しいとした世界で、この結果以上に極端なことが起きる確率」。主語が違う。", "why_asked": "「珍しい」かどうかを人の感覚だけで判断するとバラバラになる。全員が同じ数字を見て同じ基準で判断できるように、珍しさそのものを1つの確率の数字にする道具が必要になった。", "usecase": "新薬の臨床試験、A/Bテストの結果報告、論文の統計解析。ほぼすべての検定結果は、最終的にp値という1つの数字で報告される。", "opt": ["正解。帰無仮説が正しいとした世界で、この結果以上に極端なことが起きる確率がp値。", "有意水準は「これより小さければ珍しいとみなす」という判断の基準線のこと。p値と比べる相手であって、p値そのものではない。", "標準偏差はデータの散らばりの大きさを表す値で、結果の珍しさを確率で表したものではない。", "偏差値は平均と標準偏差をもとに換算した成績のものさしで、帰無仮説のもとでの確率を表す数字ではない。"]}'),

  ('stats4-q05', '仮説検定',
   'p値が計算できても、それだけでは「珍しい」と判断してよいかは決まらない。判断の合格ラインとしてあらかじめ決めておく割合（多くは5%）を何と呼ぶ？',
   NULL::text,
   '["有意水準", "p値", "検出力", "信頼区間"]',
   0, '[0]', 'single',
   '{"asked": "「珍しいと判断する基準」として先に決めておく割合の名前。", "point": "有意水準は「これより珍しければ帰無仮説を疑う」という合格ラインの割合。多くの場合5%が使われる。", "kid": "有意水準は、「p値がこの数字より小さかったら、さすがに珍しすぎるから帰無仮説を疑おう」とあらかじめ決めておく基準の割合。よく使われるのは5%（0.05）。", "eg": "跳び箱のテストで「何段跳べたら合格」のラインを、跳ぶ前に決めておくのと同じ。跳んだ結果を見てから合格ラインを動かしたら、それはズルになる。", "viz": "<svg viewBox=\"0 0 340 142\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 104 C 90 104, 110 20, 170 20 C 230 20, 250 104, 320 104\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><line x1=\"20\" y1=\"104\" x2=\"320\" y2=\"104\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><path d=\"M266 104 C 270 88, 278 62, 290 46 L 320 46 L 320 104 Z\" fill=\"#c9a04a\" opacity=\"0.4\"/><line x1=\"266\" y1=\"104\" x2=\"266\" y2=\"14\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"266\" y=\"10\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">有意水準5%のライン</text><text x=\"293\" y=\"96\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">5%</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">ここより珍しければ帰無仮説を疑う、と</text><text x=\"170\" y=\"136\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">実験の前に決めておく合格ライン</text></svg>", "terms": [["有意水準", "「珍しい」と判断する基準の割合。慣習的に5%がよく使われる"], ["有意", "有意水準より珍しいと判断された結果のこと。「偶然とは考えにくい」という意味"]], "think": "なぜ結果を見る前に基準を決めておく必要があるのかがカギ。もし結果を見たあとに「今回はp値が7%だから、基準を7%にしよう」と後出しで決めてしまうと、都合よく「珍しい」と言い放題になってしまう。そこで実験や調査を始める前に「5%より小さければ珍しいとみなす」と有意水準を先に約束しておく。こうして初めて、結果を見た人全員が同じ基準で「珍しい・珍しくない」を判断できるようになる。", "vs": "有意水準は事前に決めておく「合格ライン」、p値は実験後に計算される「実際の珍しさ」。p値が有意水準より小さければ「有意」と判断する、という比べる相手の関係。", "why_asked": "「どれくらい珍しければ疑うか」の感覚は人によって違う。研究や検定のたびに基準がぶれないよう、あらかじめ共通の合格ラインを決めておく約束事が必要になった。", "usecase": "医薬品の臨床試験や学術論文では有意水準5%（ときに1%）が慣習として使われる。品質管理の検査基準にも、同じ「先に線を引く」考え方が使われる。", "opt": ["正解。「これより珍しければ疑う」という合格ラインの割合が有意水準。多くは5%が使われる。", "p値は実験後に計算される、実際の珍しさを表す確率。有意水準はそれと比べる基準の側。", "検出力は本当に差があるときにそれを見つけられる力のことで、珍しさの合格ラインとは別の概念。", "信頼区間は推定した値が収まると考えられる幅のことで、珍しさを判断する基準の割合ではない。"]}'),

  ('stats4-q06', '仮説検定',
   '有意水準5%で検定をするとき、「思ったより高くても低くても珍しいと判断したい」場合と、「高い方向だけ珍しいと判断したい」場合とで、線の引き方が変わる。この違いを何と呼ぶ？',
   NULL::text,
   '["両側検定と片側検定", "帰無仮説と対立仮説", "第一種の過誤と第二種の過誤", "標本と母集団"]',
   0, '[0]', 'single',
   '{"asked": "「珍しい」と判断する範囲を、分布の両端に引くか片端に引くかの違い。", "point": "高くても低くても珍しいと見たいなら両側検定（両端に2.5%ずつ）。片方向だけ見たいなら片側検定（片端に5%）。", "kid": "棄却域は「ここに入ったら珍しいと判断する」と決めた範囲のこと。両側検定はその範囲を分布の両端に半分ずつ（有意水準5%なら2.5%と2.5%）置く。片側検定は「高い方だけ」のように片方の端だけに全部（5%）置く。", "eg": "体重が「増えても減っても気になる」なら両側から見張る。でも「薬を飲んだら体重が減るはず」という予想があるなら、減った方向だけを見張ればよい。見張る方角の数が違う。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M14 92 C 44 92, 52 30, 82 30 C 112 30, 120 92, 150 92\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"14\" y1=\"92\" x2=\"150\" y2=\"92\" stroke=\"#2a2f3f\"/><path d=\"M14 92 L14 68 C 16 68, 24 68, 30 92 Z\" fill=\"#3b82f6\" opacity=\"0.45\"/><path d=\"M150 92 L150 68 C 148 68, 140 68, 134 92 Z\" fill=\"#3b82f6\" opacity=\"0.45\"/><text x=\"82\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">両側検定</text><text x=\"22\" y=\"106\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">2.5%</text><text x=\"142\" y=\"106\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">2.5%</text><text x=\"82\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">高くても低くても珍しいと見る</text><line x1=\"170\" y1=\"10\" x2=\"170\" y2=\"126\" stroke=\"#2a2f3f\" stroke-dasharray=\"2 3\"/><path d=\"M190 92 C 220 92, 228 30, 258 30 C 288 30, 296 92, 326 92\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"190\" y1=\"92\" x2=\"326\" y2=\"92\" stroke=\"#2a2f3f\"/><path d=\"M326 92 L326 62 C 320 62, 300 68, 288 92 Z\" fill=\"#3b82f6\" opacity=\"0.45\"/><text x=\"258\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">片側検定</text><text x=\"310\" y=\"106\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">5%</text><text x=\"258\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">片方向だけ珍しいと見る</text></svg>", "terms": [["棄却域", "この範囲に入ったら帰無仮説を退けると決めておく、結果の範囲"], ["両側検定", "差が大きくても小さくても珍しいとみなす検定。両端に基準を置く"], ["片側検定", "あらかじめ予想した一方向だけを珍しいとみなす検定。片端に基準を置く"]], "think": "なぜ両側と片側で1つの端の広さが変わるのかがカギ。有意水準5%という「疑ってよい珍しさの総量」は変わらない。両側検定は「高い方向も低い方向も気になる」ので、その5%を両端に2.5%ずつ分けて置く。片側検定は「高い方向だけ気になる（低い方向は最初から興味の外）」ので、5%を丸ごと片方の端に集めて置く。同じ5%でも、片側検定のほうが片方の端は基準に届きやすくなる。だから片側検定は「あらかじめ方向が予想できるとき」だけ使ってよく、結果を見てから都合よく片側に切り替えるのは反則になる。", "vs": "両側・片側の使い分けは結果を見る前に決める。新しい勉強法で「上がるとも下がるとも決めつけられない」なら両側、「効果があるなら上がるはず」とはっきり予想できるなら片側、と実験前に選んでおく。", "why_asked": "同じ有意水準でも、両側と片側では「珍しい」と判定される線引きの場所が変わる。この違いを知らないと、他人の分析結果を正しく読めない。", "usecase": "新薬の効果検証は方向が予想しにくいので両側検定が基本。工場の品質検査で「不良率が悪化していないか」だけを見張るような場面では片側検定が使われることもある。", "opt": ["正解。珍しいと判断する範囲を両端に置くか片端に置くかの違いが、両側検定と片側検定。", "帰無仮説と対立仮説は、崩すために立てる仮定と本当に言いたい仮定の組であり、範囲の置き方の話ではない。", "第一種の過誤と第二種の過誤は判断を間違えたときの2種類の誤りのことで、範囲の置き方そのものではない。", "標本と母集団は調べた一部の集まりと、その元になる全体の集まりのことで、範囲の置き方とは関係がない。"]}'),

  ('stats4-q07', '仮説検定',
   '新しい勉強法を試したが、p値が有意水準より大きく「有意ではなかった」。この結果から言えることとして正しいのはどれ？',
   NULL::text,
   '["「差がある」と言えるだけの証拠が今回は得られなかった、ということ", "新しい勉強法には、はっきりと効果がないということが証明されたということ", "帰無仮説（本当は差がない）のほうが、正しいと証明されたということ", "対立仮説（本当は差がある）のほうは、間違っていたと証明されたということ"]',
   0, '[0]', 'single',
   '{"asked": "「有意ではなかった」という結果を、どこまで言い切ってよいか。", "point": "「有意でない」は「差がない証明」ではなく「差があるとまでは言い切れない」というだけ。証拠不十分と無罪は違う。", "kid": "「有意ではなかった」というのは、「差がある」と胸を張って言うには証拠が足りなかった、という意味。「差が絶対に無い」と証明されたわけではない。", "eg": "裁判の「無罪」は「絶対にやっていない」の証明ではなく、「有罪と言い切れるだけの証拠がなかった」という意味。仮説検定の「有意でない」もこれと同じ。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"66\" stroke=\"#8892a4\" stroke-width=\"2\"/><line x1=\"90\" y1=\"40\" x2=\"250\" y2=\"40\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"90\" cy=\"40\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"250\" cy=\"40\" r=\"4\" fill=\"#8892a4\"/><path d=\"M170 66 L150 78 L190 78 Z\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"90\" y=\"26\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">証拠不十分</text><text x=\"250\" y=\"26\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">有罪(差がある)</text><text x=\"170\" y=\"98\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">「有意でない」は「証拠不十分」</text><text x=\"170\" y=\"112\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">「差がない証明」ではない</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">（無罪＝絶対にやっていない、ではないのと同じ）</text></svg>", "terms": [["有意でない", "帰無仮説を退けるだけの証拠が得られなかった、という判断"], ["証明", "もう覆らないほど確かめられていること。仮説検定の結論はここまでは言えない"]], "think": "なぜ「有意でない」を「差がない証明」と言えないのかがカギ。仮説検定は、帰無仮説を退けられるだけの珍しさがあったかどうかしか見ていない。人数が少なかったり、たまたま今回のデータがばらついていたりすると、本当は差があっても「有意水準ほど珍しくはならなかった」という結果になることがある。これは「証拠が足りなかった」だけであって、「差が存在しないと確かめられた」のとはまったく違う。だから「有意でない＝差がない」と早合点すると、本当は効果があるものを見逃してしまう危険がある。", "vs": "「有意でない（証拠不十分）」と「差がないと証明された（無実の証明）」は別物。この違いを混同するのは、この単元でいちばん多い勘違い。", "why_asked": "研究や実務の報告で「差がなかった」とだけ書かれていると、「効果は絶対にない」と誤解されやすい。この言い過ぎを防ぐために、仮説検定が実際に言える範囲を正しく理解しておく必要がある。", "usecase": "薬の治験で有意差が出なかったとき、「効果が完全に否定された」と早合点せず、人数を増やして再検証する、といった判断につながる。ニュースの「効果は確認されなかった」という表現を読むときにも役立つ。", "opt": ["正解。有意でなかったのは「差があると言い切るだけの証拠が今回は得られなかった」というだけで、差がない証明ではない。", "効果がないと証明されたと言い切るのは言い過ぎ。人数を増やせば有意になっていた可能性も残っている。", "帰無仮説が正しいと証明されたわけではない。仮説検定はもともと、帰無仮説を「正しい」と証明する道具ではない。", "対立仮説が間違っていたと証明されたわけでもない。今回のデータでは証拠不十分だった、というだけにとどまる。"]}'),

  ('stats4-q08', '仮説検定',
   '本当は新しい薬に効果がないのに、検定の結果「効果がある（有意）」と判断してしまった。この間違いを何と呼ぶ？',
   NULL::text,
   '["第一種の過誤", "第二種の過誤", "有意水準", "検出力"]',
   0, '[0]', 'single',
   '{"asked": "本当は差がないのに「差がある」と判断してしまう間違いの名前。", "point": "本当は差がないのに「ある」と言ってしまう冤罪タイプの間違いが第一種の過誤。その起きやすさの上限が有意水準にあたる。", "kid": "第一種の過誤は、「本当は効果がない薬」を、たまたま珍しい結果が出たせいで「効果がある」と間違って判断してしまうこと。無実の人を有罪と判断してしまう冤罪と同じタイプの間違い。", "eg": "本当はイカサマではないふつうのコインなのに、たまたま10回中8回表が出たせいで「イカサマだ」と決めつけてしまうようなもの。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"60\" y=\"24\" width=\"240\" height=\"68\" fill=\"none\" stroke=\"#2a2f3f\"/><line x1=\"180.0\" y1=\"24\" x2=\"180.0\" y2=\"92\" stroke=\"#2a2f3f\"/><line x1=\"60\" y1=\"58.0\" x2=\"300\" y2=\"58.0\" stroke=\"#2a2f3f\"/><text x=\"120.0\" y=\"16\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">本当は差なし</text><text x=\"240.0\" y=\"16\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">本当は差あり</text><text x=\"52\" y=\"44.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">「有意」</text><text x=\"52\" y=\"78.0\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">「有意でない」</text><text x=\"120.0\" y=\"41.0\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">それ！</text><text x=\"240.0\" y=\"41.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">正しい判断</text><text x=\"120.0\" y=\"75.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">正しい判断</text><text x=\"240.0\" y=\"75.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">第二種の過誤</text><text x=\"170\" y=\"112\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">本当は差がないのに「有意」と判断</text><text x=\"170\" y=\"126\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\">＝第一種の過誤（冤罪タイプ）</text></svg>", "terms": [["第一種の過誤", "本当は差がないのに「差がある」と判断してしまう間違い。冤罪タイプ"], ["有意水準", "第一種の過誤がどれくらいの確率で起きるかの上限。5%なら「20回に1回くらいは冤罪が起きてもよしとする」基準"]], "think": "なぜ第一種の過誤がゼロにならないのかがカギ。仮説検定は「珍しいことが起きたら疑う」という仕組みなので、本当に帰無仮説が正しいときでも、まれに珍しい結果がたまたま出ることがある。有意水準を5%に決めるということは、「本当は差がないのに、たまたま珍しい結果が出て間違って有意と判断してしまう確率」を5%までは許容する、と決めていることに等しい。だから有意水準を下げれば第一種の過誤は減らせるが、次に説明する第二種の過誤（見逃し）が増えてしまう、というトレードオフがある。", "vs": "第一種の過誤は「ないのにあると言う」間違い、次に習う第二種の過誤は「あるのにないと言う」間違い。方向が逆であることを混同しやすい。", "why_asked": "検定で「有意」と出た結果を鵜呑みにすると、実は起きていない効果を信じてしまう危険がある。有意水準という基準が、そのリスクをどれだけ許容しているかを表す数字であることを理解しておく必要がある。", "usecase": "薬の承認審査で「効かないのに効くと承認してしまう」リスクの管理。工場の検査で「不良品ではないのに不良品と判定して捨ててしまう」ロスの管理にも同じ考え方が使われる。", "opt": ["正解。本当は差がないのに「差がある」と判断してしまう冤罪タイプの間違いが第一種の過誤。", "第二種の過誤は逆に、本当は差があるのに「差がない」と見逃してしまう間違い。方向が逆になる。", "有意水準は第一種の過誤が起きる確率の上限として先に決めておく基準であり、間違いそのものの名前ではない。", "検出力は本当に差があるときにそれを正しく見つけられる力のことで、間違いを指す言葉ではない。"]}'),

  ('stats4-q09', '仮説検定',
   '本当は新しい薬に効果があるのに、検定の結果「有意ではない（効果があるとは言えない）」と判断してしまった。この間違いを何と呼ぶ？',
   NULL::text,
   '["第二種の過誤", "第一種の過誤", "有意水準", "対立仮説"]',
   0, '[0]', 'single',
   '{"asked": "本当は差があるのに「差がない」と見逃してしまう間違いの名前。", "point": "本当は差があるのに見逃してしまう見逃しタイプの間違いが第二種の過誤。人数が少なかったりすると起きやすい。", "kid": "第二種の過誤は、本当は効果がある薬なのに、データの取り方やたまたまの結果のせいで「効果があるとは言えない」と判断してしまい、せっかくの効果を見逃してしまうこと。", "eg": "犯人が本当にやっているのに、証拠が集まりきらずに「無罪」となってしまうようなもの。犯人を捕まえ損ねる見逃しにあたる。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"60\" y=\"24\" width=\"240\" height=\"68\" fill=\"none\" stroke=\"#2a2f3f\"/><line x1=\"180.0\" y1=\"24\" x2=\"180.0\" y2=\"92\" stroke=\"#2a2f3f\"/><line x1=\"60\" y1=\"58.0\" x2=\"300\" y2=\"58.0\" stroke=\"#2a2f3f\"/><text x=\"120.0\" y=\"16\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">本当は差なし</text><text x=\"240.0\" y=\"16\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">本当は差あり</text><text x=\"52\" y=\"44.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">「有意」</text><text x=\"52\" y=\"78.0\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">「有意でない」</text><text x=\"120.0\" y=\"41.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">第一種の過誤</text><text x=\"240.0\" y=\"41.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">正しい判断</text><text x=\"120.0\" y=\"75.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">正しい判断</text><text x=\"240.0\" y=\"75.0\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">それ！</text><text x=\"170\" y=\"112\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">本当は差があるのに「有意でない」</text><text x=\"170\" y=\"126\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">＝第二種の過誤（見逃しタイプ）</text></svg>", "terms": [["第二種の過誤", "本当は差があるのに「差がない」と見逃してしまう間違い。見逃しタイプ"], ["検出力", "本当に差があるとき、それを正しく見つけられる力。1から第二種の過誤の起きやすさを引いたもの"]], "think": "なぜ第二種の過誤が起きるのかがカギ。本当に効果がある薬でも、試した人数が少なかったり、たまたま今回のデータの差が小さめに出たりすると、その差が有意水準ほど珍しいとまでは言えず「有意ではない」という結果になってしまうことがある。これは効果が存在しないからではなく、証拠を十分に集めきれなかったために起きる見逃しである。人数を増やすなどしてデータをたくさん集めれば、本物の効果はより見つけやすくなり、第二種の過誤は減っていく。", "vs": "第一種の過誤は「ないのにあると言う」冤罪、第二種の過誤は「あるのにないと言う」見逃し。第一種を減らそうと有意水準を厳しくすると、逆に第二種の過誤が増えやすくなる、という綱引きの関係にある。", "why_asked": "「有意ではなかった」という結果を見たとき、それが「本当に効果がない」のか「効果はあるのに見逃しただけ」なのかを見分ける発想が要る。この見逃しリスクを理解していないと、有望な薬や施策を早々にあきらめてしまう。", "usecase": "本当は効く新薬なのに、被験者の人数が少なくて「効果が確認できなかった」と判断され、開発が打ち切られてしまうケース。人数を十分に集めることの大切さを説明するときに使われる。", "opt": ["正解。本当は差があるのに「差がない」と見逃してしまう間違いが第二種の過誤。", "第一種の過誤は逆に、本当は差がないのに「差がある」と誤って判断してしまう間違い。方向が逆になる。", "有意水準は第一種の過誤の起きやすさの上限として先に決めておく基準であり、見逃しの間違いそのものではない。", "対立仮説は研究者が本当に主張したい仮説の名前であり、判断を間違えたときの誤りの種類ではない。"]}'),

  ('stats4-q10', '仮説検定',
   '薬の効果を調べる試験で、試す人数を10人から100人に増やしたところ、本当にある効果をちゃんと「有意」として見つけられる割合が上がった。この「効果を正しく見つけられる力」を何と呼ぶ？',
   NULL::text,
   '["検出力", "有意水準", "p値", "信頼区間"]',
   0, '[0]', 'single',
   '{"asked": "本当にある差を、検定で正しく見つけられる力の名前。", "point": "検出力は、本当に差があるときにそれを「有意」として正しく見つけられる確率。人数を増やすと検出力は上がる。", "kid": "検出力は、本当に効果がある薬を試したときに、それをちゃんと「効果がある」と見つけ出せる力のこと。検出力が高いほど、見逃し（第二種の過誤）が少なくなる。", "eg": "小さな音を聞き取るのに、耳を近づける（人数を増やす）ほど聞き逃しにくくなるのと同じ。人数が少ないと、小さな効果の「音」はノイズにまぎれて聞き逃してしまう。", "viz": "<svg viewBox=\"0 0 340 152\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">n=10（少人数）→ 2つの山が重なる</text><path d=\"M57 64 C 91.8 64, 97.6 32, 115 32 C 132.4 32, 138.2 64, 173 64\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M137 64 C 171.8 64, 177.6 32, 195 32 C 212.4 32, 218.2 64, 253 64\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><line x1=\"20\" y1=\"64\" x2=\"320\" y2=\"64\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"80\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">n=100（多人数）→ 山がくっきり分かれる</text><path d=\"M67 132 C 83.8 132, 86.6 104, 95 104 C 103.4 104, 106.2 132, 123 132\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M207 132 C 223.8 132, 226.6 104, 235 104 C 243.4 104, 246.2 132, 263 132\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"20\" y1=\"132\" x2=\"320\" y2=\"132\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"146\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">分かれるほど、本物の差を見つけやすい＝検出力が高い</text></svg>", "terms": [["検出力", "本当に差があるとき、それを有意として正しく見つけられる確率。1から第二種の過誤の起きやすさを引いたもの"], ["標本サイズ", "調べるために集めた人数やデータの件数"]], "think": "なぜ人数を増やすと検出力が上がるのかがカギ。試す人数が少ないと、1人1人のたまたまのばらつきの影響が大きく、本物の効果が偶然のばらつきに埋もれて見えにくくなる。人数を増やすと、たまたまのばらつきが平均されて打ち消し合い、本物の効果の差だけがくっきり浮かび上がりやすくなる。だから同じ大きさの本物の効果でも、人数が多いほど「有意」として正しく見つけられる確率（検出力）が上がり、見逃し（第二種の過誤）が減っていく。", "vs": "検出力は「本当に差があるときに、それを見つけられる力」であり、第二種の過誤は「見つけ損ねる確率」。検出力と第二種の過誤の起きやすさを足すと、ちょうど100%になる裏表の関係にある。", "why_asked": "薬の試験や実験を計画する段階で、「何人集めれば見逃さずに済むか」を決める必要がある。検出力という考え方がないと、人数を適当に決めてしまい、本物の効果があっても見逃す試験になってしまう。", "usecase": "臨床試験や実験を始める前に「検出力80%を確保するには何人必要か」を計算してから人数を決める、というのが医薬や心理学の研究の標準的な進め方。", "opt": ["正解。本当に差があるときにそれを有意として正しく見つけられる力が検出力。人数を増やすと上がる。", "有意水準は「珍しい」と判断する基準の割合であり、見つけ出す力そのものを表す言葉ではない。", "p値は今回のデータについて計算される珍しさの確率で、見つけ出す力の高さを表すものではない。", "信頼区間は推定した値が収まると考えられる幅のことで、効果を見つけ出す力の強さとは別の概念。"]}'),

  ('stats4-q11', '仮説検定',
   '新しい勉強法を試したクラス（20人）と試していないクラス（20人）の平均点を比べ、「この差は偶然の範囲か」を調べたい。2つのグループの平均の差を調べる、この定番の検定を何と呼ぶ？',
   NULL::text,
   '["t検定", "カイ二乗検定", "回帰分析", "相関分析"]',
   0, '[0]', 'single',
   '{"asked": "2つのグループの平均の差が、偶然の範囲かどうかを調べる代表的な検定。", "point": "「2つのグループの平均の差」を調べる定番はt検定。人数が少ないときの、平均の差の珍しさを計算する道具。", "kid": "t検定は、2つのグループ（勉強法を試したクラスと試していないクラスなど）の平均を比べて、「その差は偶然でも起こる範囲か、それとも珍しいほど大きいか」を調べる検定。", "eg": "2つの畑でとれたトマトの重さの平均を比べて、「品種の違いで本当に重さが変わったのか、それともたまたまか」を確かめるのと同じ発想。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"20\" y1=\"90\" x2=\"320\" y2=\"90\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"90\" x2=\"140\" y2=\"95\" stroke=\"#2a2f3f\"/><line x1=\"170\" y1=\"90\" x2=\"170\" y2=\"95\" stroke=\"#2a2f3f\"/><line x1=\"200\" y1=\"90\" x2=\"200\" y2=\"95\" stroke=\"#2a2f3f\"/><line x1=\"230\" y1=\"90\" x2=\"230\" y2=\"95\" stroke=\"#2a2f3f\"/><line x1=\"260\" y1=\"90\" x2=\"260\" y2=\"95\" stroke=\"#2a2f3f\"/><line x1=\"290\" y1=\"90\" x2=\"290\" y2=\"95\" stroke=\"#2a2f3f\"/><circle cx=\"164\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"185\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"194\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"206\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"215\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><circle cx=\"236\" cy=\"62\" r=\"4\" fill=\"#8892a4\"/><text x=\"200\" y=\"46\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">試していないクラス 平均60点</text><circle cx=\"194\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"206\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"218\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"230\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"242\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"254\" cy=\"76\" r=\"4\" fill=\"#60a5fa\"/><text x=\"224\" y=\"108\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">試したクラス 平均68点</text><line x1=\"200\" y1=\"26\" x2=\"200\" y2=\"90\" stroke=\"#8892a4\" stroke-dasharray=\"3 2\"/><line x1=\"224\" y1=\"26\" x2=\"224\" y2=\"90\" stroke=\"#3b82f6\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">この8点差はばらつきに対して偶然の範囲か？</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2つのグループの平均を比べて調べる</text></svg>", "terms": [["t検定", "2つのグループの平均の差が偶然の範囲かを調べる検定"], ["ばらつき", "各グループ内でのデータの散らばり具合。差が大きく見えても、ばらつきが大きいと「偶然」と判断されやすい"]], "think": "なぜ「平均の差」だけでなく「ばらつき」も見る必要があるのかがカギ。同じ8点の差でも、各クラスの点数がぴったりそろっている場合と、バラバラに散らばっている場合とでは意味が違う。そろっているなら8点差は本物らしいが、バラバラなら8点差くらい偶然でもよく起きる。t検定は、平均の差の大きさを、各グループ内のばらつきと人数で割って「差の珍しさ」に換算する。人数が少ないときは偶然のブレも大きくなりやすいので、t検定はそのブレ幅もふまえて珍しさを計算する。", "vs": "t検定は「平均の差」を比べる検定。次に習うカイ二乗検定は「割合の偏り」を比べる検定で、扱うデータの種類が違う（量をはかった数字か、種類分けした人数かという違い）。", "why_asked": "「2つのグループを比べて差があるかどうか」は実務でもっとも頻繁に出てくる問い。その基本となる検定の名前と役割を知らないと、A/Bテストや実験結果のレポートが読めない。", "usecase": "新しい勉強法の効果検証、新薬と偽薬の効果比較、2つの広告デザインのクリック率比較など、「平均で比べる」場面全般で使われる。", "opt": ["正解。2つのグループの平均の差が偶然の範囲かを調べる定番の検定がt検定。", "カイ二乗検定は割合やアンケートの回答の偏りが偶然かを調べる検定で、平均の比較とは違う場面で使う。", "回帰分析は1つの量からもう1つの量を予測する関係を調べる手法で、2グループの平均の差を検定するものではない。", "相関分析は2つの量が一緒に動く傾向の強さを調べる手法で、グループ間の平均の違いを調べるものではない。"]}'),

  ('stats4-q12', '仮説検定',
   'アンケートで「好きな給食」を聞いたところ、カレー・ラーメン・うどんの回答者数にばらつきがあった。この「割合の偏りは偶然の範囲か」を調べる検定を何と呼ぶ？',
   NULL::text,
   '["実際の人数と期待される人数のズレを見る、カイ二乗検定を使う", "2つのグループの平均の差を見る、t検定を使う", "2つの量が一緒に動く関係の強さを見る、相関分析を使う", "1つの量からもう1つの量を予測する関係を見る、回帰分析を使う"]',
   0, '[0]', 'single',
   '{"asked": "アンケートの回答のような割合の偏りが、偶然の範囲かを調べる検定。", "point": "「割合の偏り」を調べる定番はカイ二乗検定。実際に数えた人数と、偏りがなければこうなるはずの人数を比べる。", "kid": "カイ二乗検定は、アンケートの回答のように「いくつかの種類に分かれた人数」を数え、「この人数の偏りは偶然の範囲か、それとも珍しいほど偏っているか」を調べる検定。", "eg": "サイコロを60回振って、1〜6の目がそれぞれ何回出たかを数えるのと同じ発想。均等なら1つの目は10回くらいのはずで、それとどれだけズレているかを見る。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"40\" y=\"38.8\" width=\"26\" height=\"67.2\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"70\" y=\"58.0\" width=\"26\" height=\"48.0\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><text x=\"68\" y=\"120\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">カレー</text><rect x=\"140\" y=\"66.0\" width=\"26\" height=\"40.0\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"170\" y=\"58.0\" width=\"26\" height=\"48.0\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><text x=\"168\" y=\"120\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">ラーメン</text><rect x=\"240\" y=\"69.19999999999999\" width=\"26\" height=\"36.800000000000004\" fill=\"#3b82f6\" opacity=\"0.55\"/><rect x=\"270\" y=\"58.0\" width=\"26\" height=\"48.0\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><text x=\"268\" y=\"120\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">うどん</text><line x1=\"20\" y1=\"106\" x2=\"320\" y2=\"106\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"16\" width=\"12\" height=\"8\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"58\" y=\"23\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">実際の人数</text><rect x=\"140\" y=\"16\" width=\"12\" height=\"8\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><text x=\"158\" y=\"23\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">偏りがない場合の人数</text><text x=\"170\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">このズレの大きさが偶然の範囲かを見る</text></svg>", "terms": [["カイ二乗検定", "実際の人数（観測度数）と、偏りがない場合に予想される人数（期待度数）のズレの大きさで判断する検定"], ["観測度数と期待度数", "実際に数えた人数と、偏りがなければこうなるはずという計算上の人数"]], "think": "なぜ「実際の人数」と「予想される人数」のズレを見るのかがカギ。もし3つの給食メニューに人気の差が本当にないなら、90人のアンケートは1つのメニューにつき30人ずつになるはずである。これが「予想される人数（期待度数）」にあたる。実際に数えた人数がこの予想からどれだけズレているかを1つの数字にまとめ、そのズレが偶然の範囲を超えて大きいかどうかを判断する。ズレが大きいほど「本当に人気の差がある」と考えやすくなる。", "vs": "カイ二乗検定は「種類ごとの人数の割合」を比べる検定。t検定は「量の平均」を比べる検定で、データが種類分け（質的変数）か量をはかった数字（量的変数）かで使い分ける。", "why_asked": "アンケートや調査の結果は「何人がどれを選んだか」という形になることが多い。この種類分けデータの偏りを判断する道具がないと、割合の差が本物か偶然かを語れない。", "usecase": "選挙前の支持政党のアンケート、商品パッケージのデザイン案ごとの支持数比較、地域ごとの購入傾向の違いの検証などに使われる。", "opt": ["正解。実際の人数と偏りがない場合の予想人数のズレをもとに、割合の偏りが偶然の範囲かを調べるのがカイ二乗検定。", "t検定は2つのグループの平均の差を比べる検定で、種類ごとの人数の偏りを調べるものではない。", "相関分析は2つの量が一緒に動く傾向の強さを調べる手法で、種類分けした人数の偏りを調べるものではない。", "回帰分析は1つの量からもう1つの量を予測する関係を調べる手法で、割合の偏りを調べるものではない。"]}'),

  ('stats4-q13', '仮説検定',
   'ある研究者が、体に良さそうな食べ物の候補20個それぞれについて「本当に効果があるか」を有意水準5%で検定した。20回も検定を繰り返すと、何が起きやすくなる？',
   NULL::text,
   '["本当は効果がない食べ物でも、まぐれで「有意」と出てしまうものが混ざりやすくなる", "有意水準というあらかじめ決めた基準が、検定を重ねるたびにだんだん厳しくなっていく", "検定を繰り返すたびに、それぞれのデータのp値がどんどん小さく計算し直されていく", "対立仮説のほうが自動的に採用されやすくなり、帰無仮説という考え方自体が使えなくなる"]',
   0, '[0]', 'single',
   '{"asked": "同じ有意水準で検定を何度も繰り返すと起きる、思わぬ落とし穴。", "point": "有意水準5%は「1回の検定で20回に1回はまぐれで有意が出てもよしとする」基準。20回検定すれば、その中の1回くらいはまぐれが混ざりやすい。", "kid": "有意水準5%というのは、「本当は効果がなくても、20回に1回くらいはまぐれで『有意』と出てしまうことを許している」基準。だから、本当は効果がない食べ物ばかり20個検定しても、その中の1つくらいは「まぐれで有意」と出てしまうことがある。", "eg": "当たる確率が20分の1のくじを20回引けば、外れが続く人もいれば、1回くらい当ててしまう人も出てくる。それと同じで、まぐれの「当たり（有意）」が20回のうちどこかに紛れ込みやすい。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"12\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"28\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"44\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"60\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"76\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"92\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"108\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"124\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"140\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"156\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"172\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"188\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"204\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"220\" y=\"56\" width=\"11\" height=\"40\" fill=\"#c47070\" stroke=\"#c47070\" opacity=\"1\"/><rect x=\"236\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"252\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"268\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"284\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"300\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><rect x=\"316\" y=\"56\" width=\"11\" height=\"40\" fill=\"#2a2f3f\" stroke=\"#8892a4\" opacity=\"0.5\"/><line x1=\"8\" y1=\"96\" x2=\"332\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">本当は効果がない食べ物20個をそれぞれ検定</text><text x=\"224\" y=\"40\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">まぐれで「有意」</text><line x1=\"220\" y1=\"44\" x2=\"220\" y2=\"56\" stroke=\"#c47070\" stroke-dasharray=\"2 2\"/><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">20回に1回くらいはこうして紛れ込みやすい</text></svg>", "terms": [["多重検定", "同じデータや似た候補に対して、検定を何度も繰り返すこと"], ["まぐれの有意", "本当は効果がないのに、偶然だけで有意水準を下回ってしまうこと"]], "think": "なぜ検定を繰り返すほどまぐれが混ざりやすくなるのかがカギ。有意水準5%は、1回の検定について「本当は効果がないのに、まぐれで有意と出てしまう確率が5%まではある」という約束である。1回だけならその確率は5%と低いが、これを20回繰り返すと、20回の中のどこかで少なくとも1回はまぐれの有意が出てしまう確率はぐっと高くなる。つまり検定を繰り返すたびに、まぐれで有意になる食べ物が混ざり込むチャンスが積み重なっていく。だから多くの候補を一度に検定するときは、有意水準をより厳しくするなどの工夫をしないと、まぐれの「効果あり」を本物だと誤解してしまう。", "vs": "「1回の検定でのp値の小ささ」と「たくさんの検定を繰り返したときにまぐれが混ざる危うさ」は別の話。1つ1つの検定は正しく計算されていても、数を重ねるほど全体としての誤りやすさが増す点に注意する。", "why_asked": "「あれもこれも検定してみて、有意だったものだけ報告する」というやり方は、まぐれを本物の発見だと誤解する典型的な失敗のもとになる。この落とし穴を知らずに研究や分析をすると、再現しない「発見」を量産してしまう。", "usecase": "新聞や広告でよく見る「〇〇に効果あり」という調査は、実は多くの候補を試した中の1つだけを報告している場合がある。研究では、検定を繰り返す数に応じて有意水準を厳しくする補正が使われる。", "opt": ["正解。有意水準5%は20回に1回はまぐれが許される基準なので、20回検定すればまぐれの有意が混ざりやすい。", "有意水準はあらかじめ決めた固定の基準であり、検定を繰り返しても自動的に厳しくなったりはしない。", "p値は検定のたびにそのデータをもとに1回だけ計算される値で、繰り返すほど小さくなっていくものではない。", "対立仮説が自動的に採用されるわけではない。個々の検定の結果が有意かどうかは、あくまで1回ずつの計算による。"]}'),

  ('stats4-q14', '仮説検定',
   '薬Aと薬Bの試験はどちらも「有意」という結果だった。でも薬Aは10人、薬Bは10000人で試験していた。この2つの「有意」の重みが同じとは限らない理由を説明する、差の大きさそのものを測る数字を何と呼ぶ？',
   NULL::text,
   '["効果量", "p値", "有意水準", "検出力"]',
   0, '[0]', 'single',
   '{"asked": "「有意」とは別に、差そのものの大きさを測る数字の名前。", "point": "「有意」はサンプル数が多いほど出やすくなる。差の大きさそのものを見るには効果量を見る。", "kid": "効果量は、「その差が実際にどれくらい大きいか」を表す数字。有意かどうかとは別に、意味のある大きさの差なのか、ごくわずかな差なのかを教えてくれる。", "eg": "体重計の目盛りをどんどん細かくしていくと、朝と夜のわずかな水分の違いまで「差がある」と検出できてしまう。でもその差が「意味のある差」かどうかは、目盛りの細かさとは別の話。効果量はその「意味のある大きさかどうか」を見るものさし。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">どちらも「有意」。でも差の大きさは違う</text><path d=\"M30 56 C 63.0 56, 68.5 22 85 22 C 101.5 22, 107.0 56, 140 56\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M65 56 C 98.0 56, 103.5 22 120 22 C 136.5 22, 142.0 56, 175 56\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><line x1=\"20\" y1=\"56\" x2=\"220\" y2=\"56\" stroke=\"#2a2f3f\"/><text x=\"120\" y=\"70\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">効果量 小（重なりが多い）</text><path d=\"M207 118 C 223.8 118, 226.6 84 235 84 C 243.4 84, 246.2 118, 263 118\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><path d=\"M272 118 C 288.8 118, 291.6 84 300 84 C 308.4 84, 311.2 118, 328 118\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><line x1=\"200\" y1=\"118\" x2=\"330\" y2=\"118\" stroke=\"#2a2f3f\"/><text x=\"280\" y=\"132\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">効果量 大（重なりが少ない）</text></svg>", "terms": [["効果量", "差や関係の大きさそのものを表す数字。有意かどうかとは別の指標"], ["サンプルサイズ", "試験や調査に集めた人数やデータの件数"]], "think": "なぜ「有意」だけでは足りないのかがカギ。p値は人数を増やすほど小さくなりやすい性質を持つ。人数がとても多いと、実生活ではほとんど気にならないくらいのごく小さな差でも、有意水準を下回って「有意」と判定されてしまう。薬Bのように1万人で試験すれば、わずかな差でも有意になりやすい。だから「有意」という結果だけを見ると、差の大きさを見誤ってしまう。効果量は人数の大小に左右されにくい形で、差そのものの大きさを表すので、「統計的に有意」と「実際に意味がある大きさ」を区別するために欠かせない。", "vs": "「有意（p値が小さい）」は「偶然とは考えにくい」ことを示すだけで、「差が大きい」ことは示さない。効果量を見て初めて、その差が実生活で意味のある大きさかどうかが分かる。", "why_asked": "人数を集めれば集めるほど有意になりやすいという性質を知らないと、「有意」の一言だけで「大きな効果があった」と誤解してしまう。有意さと大きさを切り分けて考える発想が必要になった。", "usecase": "薬の効果を報告するとき、有意差だけでなく効果量もあわせて示すことで、「効くけれどわずかな効果」なのか「はっきり大きな効果」なのかを読者が判断できるようにする。", "opt": ["正解。差や関係の大きさそのものを表す数字が効果量。人数の多さに左右されにくく、有意かどうかとは別の指標。", "p値は帰無仮説のもとでの珍しさの確率であり、人数が多いほど小さくなりやすく、差の大きさそのものではない。", "有意水準は「珍しい」と判断する基準の割合であり、あらかじめ決めておく合格ラインで、差の大きさを表す数字ではない。", "検出力は本当に差があるときにそれを見つけられる力のことで、差そのものの大きさを表す数字ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
